//! Error types and result definitions for OpenFlightReader.

use thiserror::Error;

/// The primary error type for all FlightReader core operations.
#[derive(Error, Debug, Clone, PartialEq, Eq)]
pub enum FlightReaderError {
    /// The binary header is corrupted or malformed.
    #[error("Corrupted header")]
    CorruptedHeader,

    /// The header length field is invalid (e.g. neither 100 nor 101 bytes).
    #[error("Invalid header length: {length}")]
    InvalidHeaderLength {
        /// The reported header length in bytes.
        length: i16,
    },

    /// The flight log version is not supported by this parser.
    #[error("Unsupported version: {version}")]
    UnsupportedVersion {
        /// The unhandled version number.
        version: u8,
    },

    /// The record payload is shorter than the expected length specified in the record header.
    #[error("Truncated record: expected {expected} bytes, available {available}")]
    TruncatedRecord {
        /// Expected byte length.
        expected: usize,
        /// Available byte count in buffer.
        available: usize,
    },

    /// The trailing record delimiter did not match the expected 0xFF sentinel.
    #[error("Invalid record delimiter: found 0x{found:02X}")]
    InvalidRecordDelimiter {
        /// The byte encountered instead of 0xFF.
        found: u8,
    },

    /// The payload buffer is too short to perform cryptographic operations.
    #[error("Payload too short: minimum {minimum} bytes required, available {available}")]
    PayloadTooShort {
        /// Minimum required byte count.
        minimum: usize,
        /// Actual byte count available.
        available: usize,
    },

    /// The destination buffer capacity is insufficient to receive decoded bytes.
    #[error("Buffer overflow: required {required} bytes, capacity {capacity}")]
    BufferOverflow {
        /// Required byte capacity.
        required: usize,
        /// Available buffer capacity.
        capacity: usize,
    },

    /// The synchronization marker (e.g. 0x55 in .DAT streams) could not be located.
    #[error("Sync marker not found")]
    SyncNotFound,

    /// Frame checksum verification failed.
    #[error("Checksum mismatch: expected 0x{expected:08X}, calculated 0x{calculated:08X}")]
    ChecksumMismatch {
        /// Checksum value recorded in the stream.
        expected: u32,
        /// Checksum value calculated over the frame data.
        calculated: u32,
    },

    /// The length indicated in the frame header is smaller than the minimum allowable frame size.
    #[error("Invalid frame length: length {length}, minimum {minimum}")]
    InvalidFrameLength {
        /// Frame length byte read from header.
        length: u8,
        /// Minimum allowable length for this frame type.
        minimum: usize,
    },

    /// The stream ended prematurely while reading expected bytes.
    #[error("Unexpected end of file")]
    UnexpectedEof,
}

/// Convenience alias for `Result` with `FlightReaderError`.
pub type Result<T> = std::result::Result<T, FlightReaderError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_error_display_formatting() {
        assert_eq!(
            FlightReaderError::CorruptedHeader.to_string(),
            "Corrupted header"
        );
        assert_eq!(
            FlightReaderError::InvalidHeaderLength { length: 99 }.to_string(),
            "Invalid header length: 99"
        );
        assert_eq!(
            FlightReaderError::UnsupportedVersion { version: 15 }.to_string(),
            "Unsupported version: 15"
        );
        assert_eq!(
            FlightReaderError::TruncatedRecord {
                expected: 32,
                available: 16
            }
            .to_string(),
            "Truncated record: expected 32 bytes, available 16"
        );
        assert_eq!(
            FlightReaderError::InvalidRecordDelimiter { found: 0xAA }.to_string(),
            "Invalid record delimiter: found 0xAA"
        );
        assert_eq!(
            FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 1
            }
            .to_string(),
            "Payload too short: minimum 2 bytes required, available 1"
        );
        assert_eq!(
            FlightReaderError::BufferOverflow {
                required: 64,
                capacity: 32
            }
            .to_string(),
            "Buffer overflow: required 64 bytes, capacity 32"
        );
        assert_eq!(
            FlightReaderError::SyncNotFound.to_string(),
            "Sync marker not found"
        );
        assert_eq!(
            FlightReaderError::ChecksumMismatch {
                expected: 0x12345678,
                calculated: 0x87654321
            }
            .to_string(),
            "Checksum mismatch: expected 0x12345678, calculated 0x87654321"
        );
        assert_eq!(
            FlightReaderError::InvalidFrameLength {
                length: 5,
                minimum: 11
            }
            .to_string(),
            "Invalid frame length: length 5, minimum 11"
        );
        assert_eq!(
            FlightReaderError::UnexpectedEof.to_string(),
            "Unexpected end of file"
        );
    }

    #[test]
    fn test_error_equality_and_cloning() {
        let err1 = FlightReaderError::ChecksumMismatch {
            expected: 0xABCD,
            calculated: 0x1234,
        };
        let err2 = err1.clone();
        assert_eq!(err1, err2);

        let err3 = FlightReaderError::SyncNotFound;
        assert_ne!(err1, err3);
    }

    #[test]
    fn test_std_error_trait() {
        let err: Box<dyn std::error::Error> = Box::new(FlightReaderError::UnexpectedEof);
        assert_eq!(err.to_string(), "Unexpected end of file");
    }
}

//! DJI `.txt` mobile flight record parser module.
//!
//! Handles 100/101-byte fixed binary header parsing, version capability analysis,
//! and record stream iteration for DJI flight telemetry logs.

//! Cryptographic keystream and de-scrambling engine.
//!
//! Provides ECMA-182 reflected CRC64 lookup table key derivation and cyclic
//! XOR de-scrambling routines for scrambled DJI record payloads.

//! DJI on-board blackbox (`.DAT`) stream framing module.
//!
//! Implements 0x55 magic byte stream synchronization, 9-byte header extraction,
//! zero-copy payload slicing, and CRC16-CCITT / CRC32 frame checksum verification.

//! OpenFlightReader Core Engine (`flightreader-core`).
//!
//! A high-performance, zero-allocation binary parsing engine for DJI drone flight logs,
//! supporting DJI `.txt` mobile telemetry logs (v1–v14), CRC64 cyclic XOR de-scrambling,
//! and on-board hardware blackbox (`.DAT`) binary streams.

#![deny(unsafe_code)]
#![warn(missing_docs)]

pub mod crypto;
pub mod dat;
pub mod error;
pub mod txt;

pub use error::{FlightReaderError, Result};

/// Commonly used types and traits for OpenFlightReader.
pub mod prelude {
    pub use crate::error::{FlightReaderError, Result};
}

#[cfg(test)]
mod tests {
    use super::prelude::*;

    #[test]
    fn test_prelude_reexports() {
        let err = FlightReaderError::SyncNotFound;
        assert_eq!(err.to_string(), "Sync marker not found");
        let res: Result<()> = Err(err);
        assert!(res.is_err());
    }
}
